    # Each family contains parallel lines identified by a coordinate.
    families = [
        ("r", [(r, [(r, c) for c in range(w)]) for r in range(h)]),
        ("c", [(c, [(r, c) for r in range(h)]) for c in range(w)]),
        ("s", [(s, [(r, c) for r in range(h) for c in range(w) if r+c == s])
